    qweatherAuth: import_koishi16.Schema.union(["ed25519", "apikey"]).default("ed25519").description("\u548C\u98CE\u8BA4\u8BC1\u65B9\u5F0F:ed25519=\u81EA\u52A8\u7B7E\u53D1 JWT(\u9700 kid/sub/iss/\u79C1\u94A5);apikey=\u56FA\u5B9A API Key\u3002"),
