    const effective = state.effective.length ? state.effective.map((word) => `\xB7 ${word.term}${word.stable ? "(\u7A33\u5B9A)" : ""}${word.basis ? ` \u2014 ${word.basis.slice(0, 30)}` : ""}`).join("\n") : "(\u7A7A\u2014\u2014\u9996\u4E2A\u538B\u7F29\u8BC4\u4F30\u540E\u63A5\u7BA1)";
